import{_ as o,o as t,c as e,a5 as r}from"./chunks/framework.BEZBAInb.js";const _=JSON.parse('{"title":"Konado スクリプト","description":"","frontmatter":{"title":"Konado スクリプト","order":1},"headers":[],"relativePath":"ja/latest/tutorial/script/konado-script.md","filePath":"ja/latest/tutorial/script/konado-script.md","lastUpdated":1788455378000}'),i={name:"ja/latest/tutorial/script/konado-script.md"};function d(l,a,n,c,s,p){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="konadoscript" tabindex="-1">KonadoScript <a class="header-anchor" href="#konadoscript" aria-label="Permalink to &quot;KonadoScript&quot;">​</a></h1><p>KonadoScript は、ビジュアルノベル向けに設計された制作言語です（ファイル拡張子は <code>.ks</code>）。</p><p>これは、より強力で構造化された「小説の台本」のようなものと考えることができます。開発者は複雑なコードを書かなくても、物語の会話、キャラクター立ち絵、背景切り替え、音楽や効果音、ストーリー分岐、選択肢を制御できます。</p><h2 id="設計理念" tabindex="-1">設計理念 <a class="header-anchor" href="#設計理念" aria-label="Permalink to &quot;設計理念&quot;">​</a></h2><p>KonadoScript の中核となる設計理念は、<strong>物語内容</strong>と<strong>プログラムロジック</strong>を分離することです。</p><ul><li>シナリオライターはプログラミング知識なしに物語内容へ集中できます</li><li>プログラマーは物語制作に介入せず、エンジン開発へ集中できます</li><li>リソース管理（画像、音声）は識別子で参照し、スクリプトと分離します</li><li>モジュール化された命令セットにより、新機能を拡張しやすくします</li><li>Git などのバージョン管理システムと互換性があります</li><li>テキスト形式は本質的にクロスプラットフォームです</li><li>リソース参照はプラットフォームに依存しません</li></ul><h2 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to &quot;よくある質問&quot;">​</a></h2><h3 id="_1-解析エラーの処理" tabindex="-1">1. 解析エラーの処理 <a class="header-anchor" href="#_1-解析エラーの処理" aria-label="Permalink to &quot;1. 解析エラーの処理&quot;">​</a></h3><p>Godot のスクリプトエディターは、KonadoScript の構文・意味上の問題を入力中に表示します。無効な内容も <code>.ks</code> ソースには保存できますが、現在の実行時用 <code>KonadoShot</code> は更新されません。エラーを修正して再度保存すると、リソースローダーが自動的にコンパイルするため、手動で再インポートする必要はありません。</p><h3 id="_2-スクリプトファイルのエンコーディング問題" tabindex="-1">2. スクリプトファイルのエンコーディング問題 <a class="header-anchor" href="#_2-スクリプトファイルのエンコーディング問題" aria-label="Permalink to &quot;2. スクリプトファイルのエンコーディング問題&quot;">​</a></h3><p>スクリプトファイルが UTF-8 でエンコードされていることを確認してください。そうでない場合、文字化けが発生する可能性があります。デフォルトで作成されるスクリプトファイルは UTF-8 エンコードです。</p><h3 id="_3-エクスポート後のシナリオ保護" tabindex="-1">3. エクスポート後のシナリオ保護 <a class="header-anchor" href="#_3-エクスポート後のシナリオ保護" aria-label="Permalink to &quot;3. エクスポート後のシナリオ保護&quot;">​</a></h3><p>プロジェクトをエクスポートすると、Konado は現在のエクスポートプリセットにある <code>Konado -&gt; Script Encryption Key</code> を読み取り、コンパイル済みの <code>.ks</code> シナリオデータを自動的に暗号化します。鍵が空、または形式が正しくない場合は、ランダムな 256 ビット鍵を生成してそのビルドに使用します。以後のエクスポートでは、開発者が手動で変更しない限り同じ鍵が再利用されます。</p><p>パッチまたはホットアップデートを公開する場合、ベースビルドとアップデートには同じエクスポートプリセットと鍵を使用する必要があります。鍵は <code>.godot/konado_export_credentials.cfg</code> に保存されます。長期間使用する場合は、別途バックアップしてください。</p><p>ローカルでエクスポートした場合、Godot のターミナルにビルド鍵の全文が表示され、記録や問題調査に利用できます。この機能は一般的な抽出ツールで PCK からシナリオ本文を直接読み取られることを防ぐためのもので、専用 DRM の代替ではありません。エクスポートされたリソース、クライアントコード、または実行時メモリを対象に解析できる攻撃者は、シナリオ内容を復元できる場合があります。</p>',15)])])}const u=o(i,[["render",d]]);export{_ as __pageData,u as default};
